create or replace function public.pp_progress_public(p_player uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare a pp_private.starter_accounts;visible boolean;xp_total integer;begin
 if not exists(select 1 from public.profiles where player_id=p_player)then return '{}'::jsonb;end if;
 select * into a from pp_private.starter_accounts where player_id=p_player;
 visible:=p_player=auth.uid()or coalesce((select show_badges from pp_private.player_settings where player_id=p_player),true);
 select coalesce(sum(xp),0)::int into xp_total from pp_private.pixel_ledger where player_id=p_player;
 return jsonb_build_object('level',case when visible then 1+xp_total/100 else null end,'frame',coalesce(a.frame,false),'banner',coalesce(a.banner,false),'welcome',case when visible then exists(select 1 from pp_private.starter_rewards where player_id=p_player and reward='welcome')else false end,'title',case when a.title then 'Dusza imprezy'else null end,'badges',case when visible then(select coalesce(jsonb_agg(k),'[]')from(select'level10'as k where xp_total>=900 union all select'starter'where exists(select 1 from pp_private.starter_rewards where player_id=p_player and reward='finish')union all select badge from pp_private.special_profile_badges where player_id=p_player)x)else'[]'::jsonb end,'pinned',case when visible then coalesce(a.pinned,'[]')else'[]'::jsonb end);end $$;
